  if(name==='record'){const current=context,modalContext=state.modal;el.disabled=true;try{const result=await get('records/'+encodeURIComponent(state.params.get('entity'))+'/'+encodeURIComponent(id));if(current!==context||!el.isConnected||state.modal!==modalContext)return;const row=result.data;const fields=['external_id','order_number','company','name','title','email','customer_email','country','status','fulfillment_status','sku','quantity','currency','total_minor','amount_minor','unit_price_minor','method','paid_at','fulfilled_at','source_created_at','created_at'];const details=fields.filter(key=>row[key]!==null&&row[key]!==undefined&&row[key]!=='').map(key=>[l(key==='created_at'?'created':key),/_minor$/.test(key)?money(row[key],row.currency):/(?:_at)$/.test(key)?date(row[key],true):['status','fulfillment_status'].includes(key)?l(row[key]):row[key]]);details.push([l('source'),sources.find(source=>idOf(source)===row.source_id)?.name||row.source_id||'—']);state.modal={resource:'operations',row};showDialog(dialogHeader(row.order_number||row.company||row.name||row.external_id||l('details'))+'<div class="dialog-body">'+pairs(details)+(row.items?panel(l('order_items'),table([l('sku'),l('title'),l('quantity'),l('unit_price')],row.items,r=>[esc(r.sku||'—'),esc(r.title||'—'),num(r.quantity),esc(money(r.unit_price_minor,r.currency))])):'')+(row.payments?panel(l('payments'),table([l('external_id'),l('status'),l('amount'),l('created')],row.payments,r=>[esc(r.external_id),badge(r.status),esc(money(r.amount_minor,r.currency)),esc(date(r.source_created_at||r.created_at,true))])):'')+'</div><div class="dialog-footer">'+button(l('close'),'data-close-dialog')+'</div>');}finally{el.disabled=false;}return;}
