  el.disabled=true;try{let result;if(name==='sync')result=await get('sources/'+encodeURIComponent(id)+'/sync',{method:'POST',body:{}});if(name==='toggle')result=await get('automations/'+encodeURIComponent(id),{method:'PATCH',body:{version:row.version,enabled:!row.enabled}});await deps.reload();}catch(error){toast(error.message,true);el.disabled=false;}
