  const values=Object.fromEntries(new FormData(form));setFormBusy(form,true);(async()=>{try{let result;if(name==='source'){const row=state.operationsEdit;result=await get('sources'+(row?'/'+encodeURIComponent(idOf(row)):''),{method:row?'PATCH':'POST',body:row?{version:row.version,name:values.name,enabled:values.enabled==='true'}:values});}if(name==='report'){for(const key of Object.keys(values))if(!values[key])delete values[key];result=await get('reports',{method:'POST',body:{...values,language:state.lang}});}if(name==='automation'){const row=state.operationsEdit||{};result=await get('automations'+(idOf(row)?'/'+encodeURIComponent(idOf(row)):''),{method:idOf(row)?'PATCH':'POST',body:{name:values.name,kind:values.kind,interval_minutes:values.schedule_mode==='daily'?1440:Number(values.interval_minutes),enabled:values.enabled==='true',rule_id:values.kind==='rules'?(values.rule_id||null):null,config:automationConfig(values,row),...(idOf(row)?{version:row.version}:{})}});}if(name==='rule'){const row=state.operationsEdit;result=await get('rules/'+encodeURIComponent(idOf(row)),{method:'PATCH',body:{version:row.version,name:values.name,enabled:values.enabled==='true',config:Object.fromEntries(Object.keys(row.config||{}).map(key=>[key,Array.isArray(row.config[key])?String(values['cfg:'+key]||'').split(/\r?\n/).map(value=>value.trim()).filter(Boolean):key==='priority'?values['cfg:'+key]:Number(values['cfg:'+key])]))}});}setFormBusy(form,false);dialog.dataset.dirty='false';dialog.close();state.modal=null;toast(l('saved'));if(name==='report')navigate('reports',new URLSearchParams({id:idOf(result.data)}));else deps.reload();}catch(error){setFormBusy(form,false);showFormError(form,error);}})();
